// Desktop OAuth client for Google Drive sync.
//
// These values are intentionally empty in git. A release build may be
// generated by CI from the repository's Google Drive client secrets (see
// docs/GOOGLE_DRIVE_SYNC.md). For local development, prefer the
// MIKOZORA_GOOGLE_CLIENT_ID / MIKOZORA_GOOGLE_CLIENT_SECRET environment
// variables, which override these constants without editing source.
export const GOOGLE_DRIVE_CLIENT_ID = '';
export const GOOGLE_DRIVE_CLIENT_SECRET = '';
